const q = ($input.first().json.query)||{};
const ok = q['hub.verify_token'] === $vars.WHATSAPP_VERIFY_TOKEN;
return [{ json: { challenge: ok ? String(q['hub.challenge']||'') : '' } }];

const root = $input.first().json;
const body = root.body || root;
try {
  const value = body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value;
  const msg = value && value.messages && value.messages[0];
  if (!msg) return [{ json: { skip: true } }];
  const from = msg.from;
  const biz = ($vars.BUSINESS_PHONE_NUMBER||'').replace(/\D/g,'');
  if (biz && from === biz) return [{ json: { skip: true } }];
  const nombre = value.contacts && value.contacts[0] && value.contacts[0].profile && value.contacts[0].profile.name || null;
  const type = msg.type;
  let text='', media_id=null, media_type=null;
  if (type==='text') text = (msg.text&&msg.text.body)||'';
  else if (type==='image') { media_id=msg.image&&msg.image.id; media_type='image'; text=(msg.image&&msg.image.caption)||''; }
  else if (type==='document') { media_id=msg.document&&msg.document.id; media_type='document'; text=(msg.document&&msg.document.caption)||''; }
  else if (type==='interactive') text = (msg.interactive&&((msg.interactive.button_reply&&msg.interactive.button_reply.title)||(msg.interactive.list_reply&&msg.interactive.list_reply.title)))||'';
  else if (type==='button') text = (msg.button&&msg.button.text)||'';
  return [{ json: { skip:false, wa_id:from, message_id:msg.id, type, text, media_id, media_type, nombre } }];
} catch(e) { return [{ json: { skip:true, error:String(e) } }]; }

const conv0 = $('Cargar conversación').item.json;
const conv = Array.isArray(conv0)?conv0[0]:conv0;
const msg = $('Parsear evento').item.json;
const up = conv && conv.ultimo_producto ? conv.ultimo_producto : null;
const system = `Eres el CLASIFICADOR del vendedor virtual de HAUSLINE (ropa, zapatos y accesorios premium bajo pedido, Nicaragua). Devuelve SOLO un JSON valido, sin markdown. No inventes datos. Si ya habia un producto en contexto, reusalo y no lo vuelvas a preguntar. Nunca pidas el telefono. Intents: saludo, consulta_producto, consulta_precio, busqueda_codigo, busqueda_marca, consulta_seguimiento, intencion_compra, confirmacion_pedido, envio_comprobante, atencion_humana, otro. requires_human=true si hay reclamo, garantia, reembolso, molestia, problema de pago, cotizacion/descuento especial o mayoreo. Campos exactos: {\"intent\":\"\",\"requires_product_search\":false,\"search_term\":null,\"product_code\":null,\"customer_ready_to_order\":false,\"order_data\":{\"nombre\":null,\"producto\":null,\"codigo\":null,\"talla\":null,\"color\":null,\"cantidad\":null},\"missing_order_data\":[],\"requires_tracking_search\":false,\"tracking_code\":null,\"requires_human\":false,\"human_reason\":null,\"response\":\"\"}`;
const user = `Contexto (ultimo producto mostrado): ${up?JSON.stringify(up):'ninguno'}\nNombre del contacto: ${msg.nombre||'desconocido'}\nTipo de mensaje: ${msg.type}${msg.media_id?' (adjunto '+msg.media_type+')':''}\nMensaje del cliente: ${JSON.stringify(msg.text||'')}`;
return [{ json: { system, user, conv, msg } }];

const c = $input.first().json;
let raw = (c.content && c.content[0] && c.content[0].text) || (c.body && c.body.content && c.body.content[0] && c.body.content[0].text) || '{}';
raw = String(raw).trim().replace(/^```json/i,'').replace(/^```/,'').replace(/```$/,'').trim();
let intent;
try { intent = JSON.parse(raw); } catch(e){ intent = { intent:'otro', response:'¿Podrías repetirlo, por favor? Con gusto te ayudo.', requires_product_search:false, requires_tracking_search:false, requires_human:false, order_data:{}, missing_order_data:[] }; }
const prep = $('Preparar clasificador').item.json;
return [{ json: { intent, conv: prep.conv, msg: prep.msg } }];

const P = $('Parse intención').item.json;
const intent = P.intent||{}; const msg = P.msg||{}; const conv = P.conv||{};
const catalog = (()=>{ const j=$('Fetch catálogo').item.json; if(Array.isArray(j)) return j; if(j&&Array.isArray(j.data)) return j.data; if(j&&Array.isArray(j.body)) return j.body; return []; })();
let tracking = (()=>{ const j=$('Consulta tracking').item.json; if(j&&j.data!==undefined) return j.data; if(j&&j.codigo) return j; if(j&&j.body) return j.body; return null; })();

const norm=s=>(s||'').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
const ALIAS={'loubutin':'christian louboutin','louboutin':'christian louboutin','cl':'christian louboutin','gg':'golden goose','ppm':'philip model','ami':'ami paris','off white':'off-white','offwhite':'off-white','d&g':'dolce & gabbana','dolce gabanna':'dolce & gabbana','dolce&gabanna':'dolce & gabbana','louis vouitton':'louis vuitton'};
const cm=s=>{const n=norm(s);return ALIAS[n]||n;};
const precio=p=>{const o=Number(p.precio_oferta!=null?p.precio_oferta:(p.precioOferta||0)),v=Number(p.precio_venta!=null?p.precio_venta:(p.precioVenta!=null?p.precioVenta:(p.precio||0)));return o>0?o:v;};
const link=p=>`${($vars.CATALOG_URL||'https://hauslineshopni.es').replace(/\/+$/,'')}/?producto=${encodeURIComponent(p.codigo||'')}`;
const normp=p=>({codigo:p.codigo||null,nombre:p.nombre||'',marca:p.marca||null,categoria:p.categoria||null,tallas:p.tallas||[],colores:p.colores||[],precio:precio(p),imagen:p.imagen||null,enlace:link(p),tiempo_estimado:'15 a 25 días hábiles'});
function buscar(cat,o){o=o||{};const limit=o.limit||3;if(o.code){const c=norm(o.code);const e=cat.find(p=>norm(p.codigo)===c);if(e)return[normp(e)];}if(!o.term)return[];const q=norm(o.term),qm=cm(o.term),ws=q.split(' ').filter(Boolean);const sc=p=>{const n=norm(p.nombre),m=cm(p.marca),ca=norm(p.categoria),co=norm(p.codigo);let s=0;if(co===q)s+=100;if(m===qm)s+=40;if(n.indexOf(q)>=0)s+=30;if(ca===q)s+=20;for(const w of ws){if(n.indexOf(w)>=0)s+=6;if(m.indexOf(w)>=0)s+=5;if(ca.indexOf(w)>=0)s+=3;}if(p.activo===false||p.disponible===false)s-=1000;return s;};return cat.map(p=>({p,s:sc(p)})).filter(x=>x.s>0).sort((a,b)=>b.s-a.s).slice(0,limit).map(x=>normp(x.p));}

let productos=[];
if (intent.requires_product_search || intent.product_code || intent.search_term) {
  productos = buscar(catalog,{ code: intent.product_code||(intent.order_data&&intent.order_data.codigo), term: intent.search_term });
}
const up = conv && conv.ultimo_producto ? conv.ultimo_producto : null;
const ultimo_producto = productos[0] || up || null;

// Determinar ruta
let ruta='normal';
if (intent.requires_human || intent.intent==='atencion_humana') ruta='humano';
else if (intent.intent==='envio_comprobante' || (msg.media_id && msg.type!=='text')) ruta='comprobante';
else if (intent.intent==='confirmacion_pedido' && intent.customer_ready_to_order && (!intent.missing_order_data || intent.missing_order_data.length===0)) ruta='confirmar';

// Payload de borrador (solo si confirmar)
let payload=null, resumen=null;
if (ruta==='confirmar') {
  const od = intent.order_data||{};
  const prod = buscar(catalog,{ code: od.codigo, term: od.producto })[0] || ultimo_producto;
  const precioU = prod ? prod.precio : 0;
  const cant = Math.max(1, Number(od.cantidad||1));
  const total = Math.round(precioU*cant*100)/100;
  const abono = Math.round(total*0.5*100)/100;
  payload = { nombre: od.nombre||msg.nombre||conv.nombre||null, whatsapp: msg.wa_id, abono, items:[{ producto: od.producto||(prod&&prod.nombre)||'Producto', marca: prod&&prod.marca, categoria: prod&&prod.categoria, talla: od.talla, color: od.color, cantidad: cant, precio_unitario: precioU, codigo_producto: od.codigo||(prod&&prod.codigo) }] };
  resumen = { total, abono, saldo: Math.round((total-abono)*100)/100, producto: payload.items[0].producto, codigo: payload.items[0].codigo_producto, talla: od.talla, color: od.color, cantidad: cant };
}

const datos = { intent: intent.intent, response_borrador: intent.response||'', productos, tracking, resumen };
return [{ json: { wa_id: msg.wa_id, nombre: msg.nombre||conv.nombre||null, ruta, datos, payload, ultimo_producto, intent, msg } }];

const d = $input.first().json;
const datos = d.datos||{};
const system = `Eres el vendedor virtual de HAUSLINE (ropa, zapatos y accesorios premium bajo pedido, Nicaragua). Escribes por WhatsApp en español, cálido, breve (2-5 líneas). Usa SOLO los datos reales que se te pasan (productos, precios, estado del pedido). PROHIBIDO inventar precios, tallas, colores, disponibilidad, estados o fechas. Todos los productos son bajo pedido; entrega 15 a 25 días hábiles. Pago: 50% de abono para confirmar y 50% al recibir. Nunca confirmes que un pago llegó por ver una imagen. Enlace catálogo: https://hauslineshopni.es. Termina casi siempre con UNA pregunta que avance la compra. Si no hay datos, sé honesto y ofrece el catálogo. Devuelve solo el mensaje, sin comillas.`;
const user = `Intención: ${datos.intent}
Borrador sugerido: ${datos.response_borrador||''}
Productos reales encontrados: ${JSON.stringify(datos.productos||[])}
Datos de seguimiento (si aplica): ${JSON.stringify(datos.tracking||null)}
Enlace de seguimiento base: ${($vars.TRACKING_BASE_URL||'')}
Redacta la respuesta para el cliente ahora.`;
return [{ json: { system, user, wa_id: d.wa_id, nombre: d.nombre, ultimo_producto: d.ultimo_producto } }];

