const src = $('Preparar datos reales').item.json;
const borrador = (()=>{ const j=$input.first().json; if(typeof j==='string') return j; if(j&&j.data) return j.data; if(j&&j.body) return j.body; return j||''; })();
const adminLink = `${($vars.N8N_WEBHOOK_URL||'').replace(/\/+$/,'')}/webhook/hausline-aprobar-abono?token=${encodeURIComponent($vars.ADMIN_APPROVAL_SECRET||'')}&borrador=${borrador}`;
const clienteMsg = `¡Gracias! 🧾 Recibimos tu comprobante. Una persona lo revisa y en breve te confirmo tu pedido con el código de seguimiento.`;
const adminMsg = `🧾 Comprobante recibido de ${src.wa_id} (${src.nombre||'sin nombre'}).\nRevisa la imagen en el chat de WhatsApp Business. Media ID: ${src.msg&&src.msg.media_id||'-'}\nSi el abono es correcto, aprueba el pedido aquí:\n${adminLink}`;
